values.content:
=Bạn là biên tập viên website cho Eggu Sandwich. Từ bài đăng TikTok sau:
- Tiêu đề gốc: {{ $json.title }}
- Link video: {{ $json.link }}

Hãy tạo 1 bài viết ngắn cho website theo đúng định dạng JSON chuẩn (không bọc code markdown):
{
  "title": "Tiêu đề bài viết ngắn gọn dưới 70 ký tự",
  "slug": "duong-dan-bai-viet-khong-dau",
  "content": "Đoạn giới thiệu 100 từ về món ăn/sự kiện này kèm link video TikTok {{ $json.link }}"
}

parameters.jsCode:
const menuItems = [
  {
    name: "Bacon Double Cheese",
    category: "Bán chạy",
    usps: "Nhân đôi thịt xông khói áp chảo giòn thơm, đẫm phô mai Cheddar kép béo ngậy, trứng cuộn fluffy mềm mượt tan chảy",
    price: "49.000đ",
    realPhotoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7701629125517135112.jpg",
    aiPrompt: "Korean egg sandwich with double crispy bacon, abundant melted yellow cheddar cheese, silky fluffy folded scrambled eggs inside toasted golden brioche bread, served in a clean white rectangular paper takeout carton box with cute yellow poached egg logo, appetizing close-up food photography, 8k resolution, soft natural lighting"
  },
  {
    name: "Mr. Egg",
    category: "Món chữ ký",
    usps: "Bánh mì brioche nướng bơ tỏi vàng rụm, trứng cuộn fluffy béo mịn, sốt sriracha ngọt béo cay nhẹ",
    price: "39.000đ",
    realPhotoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7695023597147933959.jpg",
    aiPrompt: "Signature Korean egg sandwich, fluffy velvety scrambled eggs spilling over golden toasted brioche bread, sweet creamy sriracha drizzle, served in a minimalist cream white paper box, beautiful aesthetic Korean cafe style, professional food photography, sharp focus, 8k"
  },
  {
    name: "Sandwich Bò Nướng Teriyaki",
    category: "Đặc biệt",
    usps: "Thịt bò mềm mọng sốt Teriyaki Nhật Bản mặn ngọt đậm đà, kết hợp trứng béo và phô mai thơm lừng",
    price: "55.000đ",
    realPhotoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7702745741395053842.jpg",
    aiPrompt: "Gourmet Korean beef teriyaki egg sandwich, tender sliced beef in rich teriyaki glaze, soft scrambled eggs, melted cheese, warm brioche toast, in a branded rectangular open-top paper takeout box, studio food lighting, depth of field, 8k"
  },
  {
    name: "Sandwich Gà Giòn Sốt Cay",
    category: "Mới",
    usps: "Ức gà chiên xù giòn tan rụm, sốt cay Hàn Quốc đậm vị kết hợp phô mai béo ngậy cân bằng vị giác",
    price: "49.000đ",
    realPhotoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7691901190380064018.jpg",
    aiPrompt: "Crispy fried chicken Korean sandwich with spicy red sauce, creamy fluffy egg, melted cheese, golden brioche bread, open-top white paper food box, macro food photography, appetizing, 8k"
  },
  {
    name: "Bánh Mì Nướng Bơ Tỏi Phô Mai",
    category: "Ăn nhẹ",
    usps: "Vỏ brioche nướng bơ tỏi Pháp giòn rụm bên ngoài, mềm xốp bên trong đẫm phô mai thơm nức mũi",
    price: "35.000đ",
    realPhotoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7698288809108065537.jpg",
    aiPrompt: "Garlic butter toasted brioche sandwich overflowing with melted stretchy cheese, golden brown crust, parsley sprinkles, in a cute paper takeout container, warm cozy morning lighting, 8k"
  }
];

const today = new Date();
const dayOfWeek = today.getDay();

let angle = "";
if (dayOfWeek === 1 || dayOfWeek === 3) {
  angle = "Đồng hành công sở (Bữa sáng vội vã, ăn sạch tay, no lâu, gom đơn cùng đồng nghiệp)";
} else if (dayOfWeek === 2 || dayOfWeek === 4) {
  angle = "Cứu đói xế chiều 14h - 16h (Thèm phô mai kéo sợi ngập tràn, tiếp năng lượng giờ uể oải)";
} else if (dayOfWeek === 5) {
  angle = "Nạp năng lượng cuối tuần (Tự thưởng cho bản thân một bữa ăn chất lượng chuẩn vị Seoul)";
} else {
  angle = "Dạo phố cổ Hồ Gươm (Bánh nướng nóng hổi cầm tay dạo quanh phố 54 Nguyễn Hữu Huân)";
}

const selectedDish = menuItems[Math.floor(Math.random() * menuItems.length)];

return [
  {
    json: {
      dishName: selectedDish.name,
      dishCategory: selectedDish.category,
      dishUsps: selectedDish.usps,
      dishPrice: selectedDish.price,
      realPhotoUrl: selectedDish.realPhotoUrl,
      aiPrompt: selectedDish.aiPrompt,
      targetAngle: angle,
      date: today.toLocaleDateString("vi-VN"),
      storeAddress: "54 Nguyễn Hữu Huân, Hoàn Kiếm, Hà Nội",
      website: "eggu.vn"
    }
  }
];

let rawText = $json.content.parts[0].text.trim();
if (rawText.startsWith('```json')) {
  rawText = rawText.replace(/^```json/, '').replace(/```$/, '').trim();
} else if (rawText.startsWith('```')) {
  rawText = rawText.replace(/^```/, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    title: 'Bài viết Facebook EGGU',
    content: rawText,
    dish: $('Code - Chọn Món & Ảnh Thật & Prompt AI').item.json.dishName,
    status: 'Chờ duyệt',
    created_at: new Date().toISOString()
  };
}

const dishInfo = $('Code - Chọn Món & Ảnh Thật & Prompt AI').item.json;
const aiImageUrl = 'https://image.pollinations.ai/prompt/' + encodeURIComponent(dishInfo.aiPrompt) + '?width=1080&height=1080&nologo=true&seed=' + Date.now();

return [
  {
    json: {
      title: parsed.title || ('EGGU - ' + dishInfo.dishName),
      dishName: dishInfo.dishName,
      dishCategory: dishInfo.dishCategory,
      dishPrice: dishInfo.dishPrice,
      targetAngle: dishInfo.targetAngle,
      content: parsed.content || rawText,
      realPhotoUrl: dishInfo.realPhotoUrl,
      aiPhotoUrl: aiImageUrl,
      status: 'PENDING',
      'Mã bài viết': 'FB-' + Date.now(),
      'Tiêu đề': parsed.title || ('EGGU - ' + dishInfo.dishName),
      'Món ăn': dishInfo.dishName + ' (' + dishInfo.dishCategory + ' - ' + dishInfo.dishPrice + ')',
      'Nội dung Facebook (Đã biên tập)': parsed.content || rawText,
      '📸 ẢNH THẬT CỦA QUÁN (Bao bì chuẩn 100%)': dishInfo.realPhotoUrl,
      '🎨 ẢNH AI TẠO (Phong cách Hàn Quốc)': aiImageUrl,
      'Gợi ý đăng bài': 'Đăng bài kèm 1 hoặc cả 2 ảnh trên Fanpage!',
      'Trạng thái': 'Chờ nhân viên copy',
      'Thời gian tạo': new Date().toLocaleString('vi-VN')
    }
  }
];
